65: func newReviewCapBinding(targets []store.ReviewTarget) (reviewCapBinding, error) {
66: 	if len(targets) == 0 {
67: 		return reviewCapBinding{}, axi.Failure("review_cap_unsupported", "Review cap Decisions require at least one changed candidate", false)
68: 	}
69: 	targets = slices.Clone(targets)
70: 	slices.SortFunc(targets, func(a, b store.ReviewTarget) int { return strings.Compare(a.Repository, b.Repository) })
71: 	if len(targets) == 1 {
72: 		return reviewCapBinding{Head: targets[0].Commit, Targets: targets}, nil
73: 	}
74: 	hash := sha256.New()
75: 	for _, target := range targets {
76: 		fmt.Fprintf(hash, "%s\x00%s\n", target.Repository, target.Commit)
77: 	}
78: 	return reviewCapBinding{Head: hex.EncodeToString(hash.Sum(nil)), Targets: targets}, nil
