121: func createReviewCapNotice(ctx context.Context, db *store.DB, project store.Project, task store.Task, binding reviewCapBinding, used, max int) error {
122: 	head := binding.Head
123: 	if err := db.ObsoleteStaleReviewCapDecisions(ctx, task.ID, reviewCapOrigin(task, head)); err != nil {
124: 		return err
125: 	}
126: 	data := marshalJSON(map[string]any{"head_sha": head, "targets": binding.Targets, "rounds_used": used, "max_rounds": max})
127: 	var exists bool
128: 	if err := db.QueryRowContext(ctx, `SELECT EXISTS(
129: 		SELECT 1 FROM notices n
130: 		WHERE n.task_id=? AND n.kind='review_cap_reached'
131: 		AND n.id=(SELECT MAX(latest.id) FROM notices latest WHERE latest.task_id=n.task_id AND latest.kind='review_cap_reached')
132: 		AND json_valid(n.data_json) AND json_extract(n.data_json,'$.head_sha')=?
133: 		AND (NOT EXISTS(SELECT 1 FROM decisions d WHERE d.project_id=n.project_id AND d.origin='notice:'||n.id)
134: 			OR EXISTS(SELECT 1 FROM decisions d WHERE d.project_id=n.project_id AND d.origin='notice:'||n.id AND d.answered_at=0 AND d.obsolete_at=0))
135: 	)`, task.ID, head).Scan(&exists); err != nil {
136: 		return err
137: 	}
138: 	if exists {
139: 		return nil
140: 	}
141: 	_, err := db.CreateNotice(ctx, store.Notice{ProjectID: project.ID, TaskID: task.ID, Kind: "review_cap_reached", Summary: fmt.Sprintf("%s: Review and repair cap reached at head %s (%s)", task.Title, binding.label(), reviewCapUsageDescription(task, used, max)), DataJSON: data})
142: 	return err
143: }
