+	}
+	if findingKey == "" {
+		findingKey = "unsafe-operation-after-repair"
+	}
+	recordReviewRound(t, f, changeSeq, "changes_requested", blockingFindings(findingKey, "review-issue.txt", "repaired operation"))
+}
