58: // reviewCapBinding is what a cap Decision binds: the one candidate head of a
59: // single repository, or a digest of every changed workspace Member's head.
60: type reviewCapBinding struct {
61: 	Head    string
62: 	Targets []store.ReviewTarget
63: }
